// billing-service/src/invoice/InvoiceService.ts
import { Customer } from '../../shared/customer/Customer';
import { SalesOrder } from '../../sales/order/SalesOrder';

export class InvoiceService {
  createInvoice(salesOrder: SalesOrder): Invoice {
    const customer = salesOrder.customer; // direct object ref across context
    return new Invoice({
      customerId: customer.id,
      billingAddress: customer.shippingAddress, // Sales field in Billing
      creditLimit: customer.leadScore * 1000,   // Sales concept used for billing
      lineItems: salesOrder.lineItems,           // Sales internal exposed
    });
  }
}
